<?php $l=$this->getVar('liveclassLabels');$s=$this->getVar('liveclassSession');$e=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$icons=$this->getObject('iconservice','ui');$manage=$this->getVar('liveclassMayManage',false); ?>
<section class="liveclass-page"><header><p class="chisimba-eyebrow"><?php echo $e($l[$s['session_type']==='webinar'?'webinar_type':'context_type']); ?></p><h1><?php echo $e($s['name']); ?></h1><p><?php echo nl2br($e($s['description'])); ?></p></header><?php if($this->getVar('liveclassMessage','')!==''): ?><p class="chisimba-notice chisimba-notice-success"><?php echo $e($this->getVar('liveclassMessage')); ?></p><?php endif; ?><?php if($this->getVar('liveclassError','')!==''): ?><p class="chisimba-notice chisimba-notice-error"><?php echo $e($this->getVar('liveclassError')); ?></p><?php endif; ?><dl class="liveclass-details"><dt><?php echo $e($l['starts']); ?></dt><dd><?php echo $e($s['starts_at']); ?></dd><dt><?php echo $e($l['duration']); ?></dt><dd><?php echo (int)$s['duration_minutes']; ?></dd></dl><div class="chisimba-form-actions"><?php if($s['status']==='scheduled'): ?><a class="button chisimba-button-primary" href="<?php echo $e($this->uri(array('action'=>'join','id'=>$s['id']))); ?>"><?php echo $icons->render($manage?'play':'log-in',array('decorative'=>true)); ?><span><?php echo $e($l[$manage?'start':'join']); ?></span></a><?php endif; ?><?php if($manage&&$s['status']==='scheduled'): ?><form method="post" action="<?php echo $e($this->uri(array('action'=>'end','id'=>$s['id']))); ?>"><input type="hidden" name="csrf_token" value="<?php echo $e($this->getVar('liveclassCsrf')); ?>"><button class="button chisimba-button-secondary" type="submit"><?php echo $icons->render('square',array('decorative'=>true)); ?><span><?php echo $e($l['end']); ?></span></button></form><form method="post" action="<?php echo $e($this->uri(array('action'=>'cancel','id'=>$s['id']))); ?>"><input type="hidden" name="csrf_token" value="<?php echo $e($this->getVar('liveclassCsrf')); ?>"><button class="button chisimba-button-danger" type="submit"><?php echo $icons->render('x',array('decorative'=>true)); ?><span><?php echo $e($l['cancel_session']); ?></span></button></form><?php endif; ?></div><section><h2><?php echo $e($l['recordings']); ?></h2><?php $recordings=$this->getVar('liveclassRecordings',array());if(!$recordings): ?><p><?php echo $e($l['no_recordings']); ?></p><?php else: ?><div class="liveclass-grid"><?php foreach($recordings as $recording): ?><article class="liveclass-card"><h3><?php echo $e($recording['name']); ?></h3><?php foreach($recording['formats'] as $format): ?><a class="button chisimba-button-secondary" href="<?php echo $e($format['url']); ?>" rel="noopener"><?php echo $icons->render('play',array('decorative'=>true)); ?><span><?php echo $e($format['type']); ?></span></a><?php endforeach; ?></article><?php endforeach; ?></div><?php endif; ?></section></section>
